import {readFileSync} from 'node:fs';
import {resolve} from 'node:path';
import {parseArgs} from 'node:util';
import {RUNNER_CONFIG} from '../src/lib/agent/config';
import {languageModel} from '../src/lib/agent/model';
import {MODELS, providerOf} from '../src/lib/agent/models';
import {evalCredential, parseTaskMarkdown, parseTasks, previewScreenshot, runTasks} from '../src/lib/agent/runner';
import {flushTraces} from '../src/lib/agent/trace';
import {createProject, sandboxConfigured} from '../src/lib/sandbox/sandbox';

const {values} = parseArgs({
  options: {
    tasks: {type: 'string'},
    runs: {type: 'string', default: '1'},
    concurrency: {type: 'string', default: String(RUNNER_CONFIG.concurrency)},
    model: {type: 'string', default: MODELS[0].id},
    out: {type: 'string', default: `.scratch/agent-runs/${new Date().toISOString().replace(/[:.]/g, '-')}`},
  },
});

const cwd = process.env.INIT_CWD ?? process.cwd();
if (!values.tasks) throw new Error('Usage: bun run agent:run --tasks <file.md|file.json> --runs <k> [--concurrency n] [--model id] [--out dir]');
if (!sandboxConfigured()) throw new Error('Set the Vercel sandbox credentials in apps/web/.env.');
const taskText = readFileSync(resolve(cwd, values.tasks), 'utf8');
const tasks = values.tasks.endsWith('.md') ? parseTaskMarkdown(taskText) : parseTasks(JSON.parse(taskText));
const provider = providerOf(values.model);
if (!provider) throw new Error(`Unknown model ${values.model}. Pick one of: ${MODELS.map(m => m.id).join(', ')}.`);
const credential = evalCredential(provider, process.env);
const outDir = resolve(cwd, values.out);

const results = await runTasks({
  tasks,
  runs: Number(values.runs),
  concurrency: Number(values.concurrency),
  outDir,
  model: () => languageModel(values.model, credential),
  project: () => createProject(),
  capture: project => previewScreenshot(project),
  log: line => console.log(line),
});
await flushTraces();
console.log(`${results.length} runs written to ${outDir}`);
import {mkdir, writeFile} from 'node:fs/promises';
import {join} from 'node:path';
import {setTimeout as delay} from 'node:timers/promises';
import type {LanguageModel} from 'ai';
import type {Project} from '../sandbox/project';
import {CHECKER_DIR, CHECKER_SCRIPT} from '../sandbox/runtime-check';
import {PREVIEW_PORT} from '../sandbox/starter';
import {RUNNER_CONFIG} from './config';
import {RATE_LIMITED, SANDBOX_QUOTA, sandboxQuotaExceeded} from './errors';
import {runAgent} from './run';
import {maskSecrets} from './trace';
import type {ProviderCredential, ProviderId, SandboxUsage, TurnRecord, TurnStatus} from './types';

export type Task = {id: string; prompt: string} & Record<string, unknown>;
export type RunSummary = {taskId: string; run: number; status: TurnStatus; attempts: number; dir: string};

type Deps = {
  model: () => Exclude<LanguageModel, string>;
  project: () => Promise<Project>;
  capture: (project: Project) => Promise<Uint8Array | null>;
  sleep?: (ms: number) => Promise<unknown>;
  log?: (line: string) => void;
};

export function parseTasks(value: unknown): Task[] {
  if (!Array.isArray(value) || value.length === 0) throw new Error('The task file must be a non-empty JSON array.');
  const ids = new Set<string>();
  return value.map((task: Record<string, unknown> | null, i) => {
    const id = task?.id;
    if (typeof id !== 'string' || !/^[\w.-]+$/.test(id)) throw new Error(`Task ${i} needs an id of letters, digits, ".", "-" or "_".`);
    if (typeof task?.prompt !== 'string' || !task.prompt) throw new Error(`Task ${id} needs a prompt.`);
    if (ids.has(id)) throw new Error(`Task id ${id} is used twice.`);
    ids.add(id);
    return task as Task;
  });
}

const STARTERS = ['default'];

// The founder's Markdown task format: one "## <task id>" section per task with "prompt:", "starter:" and "notes:" lines.
// Notes are for the founder and never reach the runner; anything before the first heading is ignored.
export function parseTaskMarkdown(text: string): Task[] {
  const sections = text.split(/^## +/m).slice(1);
  if (!sections.length) throw new Error('The task file has no "## <task id>" sections.');
  return parseTasks(
    sections.map(section => {
      const [heading, ...lines] = section.split('\n');
      const id = heading.trim();
      const field = (name: string) => lines.find(l => l.startsWith(`${name}:`))?.slice(name.length + 1).trim();
      const prompt = field('prompt');
      if (!prompt) throw new Error(`Task ${id} needs a prompt.`);
      const starter = field('starter') || 'default';
      if (!STARTERS.includes(starter)) throw new Error(`Task ${id} uses starter "${starter}"; available: ${STARTERS.join(', ')}.`);
      return {id, prompt, starter};
    }),
  );
}

const EVAL_KEYS: Record<ProviderId, string> = {openai: 'OPENAI_EVAL_API_KEY', anthropic: 'ANTHROPIC_EVAL_API_KEY'};

export function evalCredential(provider: ProviderId, env: Record<string, string | undefined>): ProviderCredential {
  const apiKey = env[EVAL_KEYS[provider]];
  if (!apiKey) throw new Error(`Set ${EVAL_KEYS[provider]} in apps/web/.env. The runner never uses a user key.`);
  return {provider, kind: 'api-key', apiKey};
}

const SHOT = `${CHECKER_DIR}/preview.png`;

export async function previewScreenshot(project: Project, sleep: (ms: number) => Promise<unknown> = delay) {
  for (let attempt = 0; attempt < 3; attempt++) {
    const {exitCode} = await project.run('node', [CHECKER_SCRIPT, `http://localhost:${PREVIEW_PORT}`, SHOT]);
    if (exitCode === 0) return project.readBytes(SHOT);
    await sleep(3_000);
  }
  return null;
}

async function runOnce(task: Task, run: number, outDir: string, deps: Required<Deps>): Promise<RunSummary> {
  for (let attempt = 1; ; attempt++) {
    const project = await deps.project();
    let record: TurnRecord;
    let before: Uint8Array | null;
    let after: Uint8Array | null = null;
    let usage: SandboxUsage | null = null;
    try {
      before = await deps.capture(project);
      const {stream, turn} = runAgent({model: deps.model(), messages: [{role: 'user', content: task.prompt}], project, keepSandbox: true});
      for await (const _ of stream);
      record = await turn;
      if (record.error !== RATE_LIMITED) after = await deps.capture(project);
    } finally {
      usage = (await project.stop?.().catch(() => null)) ?? null;
    }
    record.sandbox = usage;
    if (record.error === RATE_LIMITED && attempt < RUNNER_CONFIG.maxAttempts) {
      const wait = RUNNER_CONFIG.backoffMs * 2 ** (attempt - 1);
      deps.log(`${task.id} run ${run}: rate limited, retrying in ${wait / 1000}s`);
      await deps.sleep(wait);
      continue;
    }
    const dir = join(outDir, task.id, `run-${run}`);
    const json = (value: unknown) => maskSecrets(JSON.stringify(value, null, 2));
    await mkdir(dir, {recursive: true});
    await writeFile(join(dir, 'task.json'), json(task));
    await writeFile(join(dir, 'turn.json'), json(record));
    await writeFile(join(dir, 'diff.patch'), maskSecrets(record.diff));
    await writeFile(join(dir, 'verify.json'), json({verify: record.verify, repairAttempted: record.repairAttempted, repairVerify: record.repairVerify}));
    if (before) await writeFile(join(dir, 'before.png'), before);
    if (after) await writeFile(join(dir, 'after.png'), after);
    deps.log(`${task.id} run ${run}: ${record.status}, sandbox ${JSON.stringify(record.sandbox)}`);
    return {taskId: task.id, run, status: record.status, attempts: attempt, dir};
  }
}

export async function runTasks({
  tasks,
  runs,
  outDir,
  concurrency = RUNNER_CONFIG.concurrency,
  ...deps
}: {tasks: Task[]; runs: number; outDir: string; concurrency?: number} & Deps): Promise<RunSummary[]> {
  const all: Required<Deps> = {sleep: delay, log: () => {}, ...deps};
  const jobs = tasks.flatMap(task => Array.from({length: runs}, (_, i) => ({task, run: i + 1})));
  const results: RunSummary[] = [];
  let next = 0;
  let paused = false;
  const worker = async () => {
    while (!paused && next < jobs.length) {
      const {task, run} = jobs[next++];
      try {
        results.push(await runOnce(task, run, outDir, all));
      } catch (error) {
        if (!sandboxQuotaExceeded(error)) throw error;
        if (!paused) all.log(SANDBOX_QUOTA);
        paused = true;
      }
    }
  };
  const workers = Math.min(concurrency, RUNNER_CONFIG.concurrency, jobs.length);
  await Promise.all(Array.from({length: workers}, worker));
  return results;
}
import type {Project} from '../sandbox/project';
import {CHECKER_SCRIPT} from '../sandbox/runtime-check';
import {PREVIEW_PORT} from '../sandbox/starter';
import type {VerifyCheck, VerifyResult} from './types';

const MAX_ERROR_LINES = 40;
const tail = (output: string) => output.trim().split('\n').slice(-MAX_ERROR_LINES).join('\n');

async function timed(name: VerifyCheck['name'], fn: () => Promise<Omit<VerifyCheck, 'name' | 'durationMs'>>): Promise<VerifyCheck> {
  const start = Date.now();
  return {name, ...(await fn()), durationMs: Date.now() - start};
}

const script = (project: Project, name: 'typecheck' | 'build') =>
  timed(name, async () => {
    const {exitCode, output} = await project.run('npm', ['run', '--silent', name]);
    return exitCode === 0 ? {status: 'passed', errors: []} : {status: 'failed', errors: [tail(output)]};
  });

export function runtimeErrors(exitCode: number, output: string): Omit<VerifyCheck, 'name' | 'durationMs'> {
  const json = output.trim().split('\n').at(-1) ?? '';
  if (exitCode !== 0 || !json.startsWith('[')) return {status: 'skipped', errors: [`The runtime check could not run: ${tail(output)}`]};
  const errors: string[] = JSON.parse(json);
  return errors.length ? {status: 'failed', errors} : {status: 'passed', errors: []};
}

export async function verifyProject(project: Project): Promise<VerifyResult> {
  const typecheck = await script(project, 'typecheck');
  const build = await script(project, 'build');
  const runtime =
    build.status === 'failed'
      ? {name: 'runtime' as const, status: 'skipped' as const, errors: [], durationMs: 0}
      : await timed('runtime', async () => {
          const {exitCode, output} = await project.run('node', [CHECKER_SCRIPT, `http://localhost:${PREVIEW_PORT}`]);
          return runtimeErrors(exitCode, output);
        });
  const checks = [typecheck, build, runtime];
  return {ok: checks.every(c => c.status !== 'failed'), checks};
}
// Founder-owned: write the system prompt here. Empty means no instructions are sent.
export const SYSTEM_PROMPT = '';

// Founder-owned: the message the agent gets for its one repair attempt. {errors} is replaced with the failing checks.
export const REPAIR_PROMPT = 'Verify failed after your change. Fix these errors:\n\n{errors}';
import type {ToolName} from './types';

export const AGENT_CONFIG = {
  maxSteps: 20,
  maxOutputTokens: 32_000,
  effort: 'medium',
  thinkingDisplay: 'summarized',
  tools: ['list_files', 'read_file', 'search', 'edit_file', 'write_file', 'typecheck'] satisfies ToolName[],
  deniedPaths: ['.git', 'node_modules'],
  approvalFiles: ['package.json', 'package-lock.json', '*.lock', 'pnpm-lock.yaml', 'tsconfig*.json', '*.config.*', '.env*'],
  maxToolOutputChars: 20_000,
  promptCachePerProject: true,
} as const;

export const RUNNER_CONFIG = {
  concurrency: 3,
  maxAttempts: 3,
  backoffMs: 5_000,
} as const;

export const SANDBOX_CONFIG = {
  vcpus: 2,
  timeoutMs: 10 * 60_000,
  snapshotExpirationMs: 7 * 24 * 60 * 60_000,
} as const;
import type {ProviderId} from './types';

export const MODELS: {id: string; label: string; provider: ProviderId}[] = [
  {id: 'claude-sonnet-5-5', label: 'Claude Sonnet 5.5', provider: 'anthropic'},
  {id: 'gpt-5.5', label: 'GPT-5.5', provider: 'openai'},
  {id: 'gpt-5', label: 'GPT-5', provider: 'openai'},
];

export function providerOf(modelId: string | undefined): ProviderId | null {
  return MODELS.find(m => m.id === modelId)?.provider ?? null;
}
import {createAnthropic} from '@ai-sdk/anthropic';
import {createOpenAI} from '@ai-sdk/openai';
import {providerOf} from './models';
import type {ProviderCredential} from './types';

export function languageModel(modelId: string, credential: ProviderCredential) {
  if (providerOf(modelId) !== credential.provider) {
    throw new Error(`Model ${modelId} is not available for provider ${credential.provider}.`);
  }
  if (credential.provider === 'anthropic') {
    if (credential.kind !== 'api-key') throw new Error('Anthropic accepts API keys only.');
    return createAnthropic({apiKey: credential.apiKey})(modelId);
  }
  const token = credential.kind === 'api-key' ? credential.apiKey : credential.accessToken;
  return createOpenAI({apiKey: token})(modelId);
}

// Body credentials are API keys only; an OAuth token must come from the server-side session cookie.
export function parseCredential(value: unknown): ProviderCredential | null {
  if (typeof value !== 'object' || value === null) return null;
  const c = value as Record<string, unknown>;
  if ((c.provider !== 'openai' && c.provider !== 'anthropic') || c.kind !== 'api-key' || typeof c.apiKey !== 'string' || !c.apiKey) return null;
  return {provider: c.provider, kind: c.kind, apiKey: c.apiKey};
}

