import {posix} from 'node:path';
import {jsonSchema, tool, type ToolSet} from 'ai';
import type {Project} from '../sandbox/project';
import {AGENT_CONFIG} from './config';
import {checkPolicy} from './policy';
import type {ToolCallRecord, ToolName} from './types';

const pathProp = {type: 'string', description: 'Path relative to the project root.'};

export const TOOL_DEFINITIONS = {
  list_files: {
    description: 'List project files under a folder, skipping node_modules, .git and dist.',
    schema: {type: 'object', properties: {path: {...pathProp, default: '.'}}, additionalProperties: false},
  },
  read_file: {
    description: 'Read a text file.',
    schema: {type: 'object', properties: {path: pathProp}, required: ['path'], additionalProperties: false},
  },
  search: {
    description: 'Search file contents for a regular expression. Returns matching lines as path:line:text.',
    schema: {
      type: 'object',
      properties: {query: {type: 'string'}, path: {...pathProp, default: '.'}},
      required: ['query'],
      additionalProperties: false,
    },
  },
  edit_file: {
    description: 'Replace one exact, unique occurrence of oldString with newString in a file. Include enough surrounding text to make oldString unique.',
    schema: {
      type: 'object',
      properties: {path: pathProp, oldString: {type: 'string'}, newString: {type: 'string'}},
      required: ['path', 'oldString', 'newString'],
      additionalProperties: false,
    },
  },
  write_file: {
    description: 'Create a file or replace its whole content.',
    schema: {
      type: 'object',
      properties: {path: pathProp, content: {type: 'string'}},
      required: ['path', 'content'],
      additionalProperties: false,
    },
  },
  typecheck: {
    description: 'Run the project typecheck (tsc --noEmit) and return its output.',
    schema: {type: 'object', properties: {}, additionalProperties: false},
  },
} satisfies Record<ToolName, {description: string; schema: object}>;

type Input = {path?: string; query?: string; oldString?: string; newString?: string; content?: string};

const clip = (text: string) =>
  text.length > AGENT_CONFIG.maxToolOutputChars ? `${text.slice(0, AGENT_CONFIG.maxToolOutputChars)}\n[truncated]` : text;

const countOf = (text: string, part: string) => (part ? text.split(part).length - 1 : 0);

export function proposedDiff(path: string, before: string | null, after: string) {
  const lines = (text: string, sign: string) => (text ? text.split('\n').map(l => `${sign}${l}`) : []);
  return [`--- a/${path}`, `+++ b/${path}`, ...lines(before ?? '', '-'), ...lines(after, '+')].join('\n');
}

export function applyEdit(content: string, oldString: string, newString: string): string {
  const matches = countOf(content, oldString);
  if (matches === 0) throw new Error('oldString was not found. Read the file and copy the exact text.');
  if (matches > 1) throw new Error(`oldString matches ${matches} places. Include more surrounding text.`);
  return content.replace(oldString, () => newString);
}

async function execute(project: Project, name: ToolName, input: Input, rel: string) {
  const abs = posix.join(project.root, rel);
  switch (name) {
    case 'list_files':
      return clip((await project.list(abs)).sort().join('\n'));
    case 'read_file': {
      const content = await project.read(abs);
      if (content === null) throw new Error(`${rel} does not exist.`);
      return clip(content);
    }
    case 'search':
      return clip(await project.search(input.query ?? '', abs)) || 'No matches.';
    case 'edit_file': {
      const content = await project.read(abs);
      if (content === null) throw new Error(`${rel} does not exist.`);
      await project.write(abs, applyEdit(content, input.oldString ?? '', input.newString ?? ''));
      return `Edited ${rel}.`;
    }
    case 'write_file':
      await project.write(abs, input.content ?? '');
      return `Wrote ${rel}.`;
    case 'typecheck': {
      const {exitCode, output} = await project.run('npm', ['run', '--silent', 'typecheck']);
      return {ok: exitCode === 0, output: clip(output.trim()) || 'No type errors.'};
    }
  }
}

export function createTools(project: Project, toolCalls: ToolCallRecord[]): ToolSet {
  let writes = Promise.resolve();
  const writeTurn = async (name: ToolName) => {
    let release = () => {};
    if (name !== 'write_file' && name !== 'edit_file') return release;
    const previous = writes;
    writes = new Promise(resolve => (release = resolve));
    await previous;
    return release;
  };
  const entries = AGENT_CONFIG.tools.map(name => [
    name,
    tool({
      description: TOOL_DEFINITIONS[name].description,
      inputSchema: jsonSchema<Input>(TOOL_DEFINITIONS[name].schema),
      execute: async (input, {toolCallId}) => {
        const decision = checkPolicy(name, input, project.root);
        if (decision.type === 'deny') throw new Error(decision.message);
        const release = await writeTurn(name);
        const startedAt = new Date();
        const record: ToolCallRecord = {
          id: toolCallId,
          tool: name,
          args: input,
          result: null,
          decision: decision.type === 'approve' ? 'approved' : 'allowed',
          startedAt: startedAt.toISOString(),
          durationMs: 0,
        };
        toolCalls.push(record);
        try {
          record.result = await execute(project, name, input, decision.path ?? '.');
          return record.result;
        } catch (error) {
          record.result = {error: error instanceof Error ? error.message : String(error)};
          throw error;
        } finally {
          record.durationMs = Date.now() - startedAt.getTime();
          release();
        }
      },
    }),
  ]);
  return Object.fromEntries(entries);
}
import {posix} from 'node:path';
import {AGENT_CONFIG} from './config';
import type {DeniedCall} from './types';

export type PolicyDecision =
  | {type: 'allow'; path?: string}
  | {type: 'approve'; path: string}
  | {type: 'deny'; reason: DeniedCall['reason']; message: string};

const WRITE_TOOLS: string[] = ['edit_file', 'write_file'];
const globToRegExp = (glob: string) =>
  new RegExp(`^${glob.split('*').map(s => s.replace(/[.+?^${}()|[\]\\]/g, '\\$&')).join('.*')}$`);
const APPROVAL_FILES = AGENT_CONFIG.approvalFiles.map(globToRegExp);

export function checkPolicy(tool: string, input: unknown, root: string): PolicyDecision {
  if (!(AGENT_CONFIG.tools as readonly string[]).includes(tool)) {
    return {type: 'deny', reason: 'not-allowlisted', message: `The ${tool} tool is not allowed.`};
  }
  const path = (input as {path?: unknown} | null)?.path;
  if (path === undefined) return {type: 'allow'};
  if (typeof path !== 'string') return {type: 'deny', reason: 'outside-project', message: 'The path must be a string.'};

  const rel = posix.relative(root, posix.resolve(root, path));
  if (rel === '..' || rel.startsWith('../') || posix.isAbsolute(rel)) {
    return {type: 'deny', reason: 'outside-project', message: `${path} is outside the project folder.`};
  }
  if ((AGENT_CONFIG.deniedPaths as readonly string[]).includes(rel.split('/')[0])) {
    return {type: 'deny', reason: 'outside-project', message: `${path} is not part of the editable project.`};
  }
  if (WRITE_TOOLS.includes(tool) && APPROVAL_FILES.some(re => re.test(posix.basename(rel)))) {
    return {type: 'approve', path: rel};
  }
  return {type: 'allow', path: rel};
}
import {execFileSync} from 'node:child_process';
import {mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {dirname, join, relative} from 'node:path';
import {readUIMessageStream, simulateReadableStream, type LanguageModel, type ModelMessage} from 'ai';
import {convertArrayToReadableStream} from 'ai/test';
import type {Project} from '../sandbox/project';
import {runAgent, type AgentChunk} from './run';
import type {AgentMessage} from './types';

export type Scripted = (cmd: string, args: string[]) => {exitCode: number; output: string} | undefined;

export function tempProject(files: Record<string, string>, scripted: Scripted = () => ({exitCode: 0, output: ''})) {
  const root = mkdtempSync(join(tmpdir(), 'betterlook-test-'));
  for (const [path, content] of Object.entries(files)) {
    mkdirSync(dirname(join(root, path)), {recursive: true});
    writeFileSync(join(root, path), content);
  }
  const sh = (cmd: string, args: string[]) => {
    try {
      return {exitCode: 0, output: execFileSync(cmd, args, {cwd: root, stdio: 'pipe'}).toString()};
    } catch (error) {
      const e = error as {status?: number; stdout?: Buffer; stderr?: Buffer};
      return {exitCode: e.status ?? 1, output: `${e.stdout ?? ''}${e.stderr ?? ''}`};
    }
  };
  for (const args of [['init', '-q'], ['config', 'user.name', 'T'], ['config', 'user.email', 't@t.invalid'], ['add', '-A'], ['commit', '-qm', 'starter']]) sh('git', args);
  const project: Project = {
    id: 'sbx-local',
    root,
    list: async d => sh('find', [d, '-type', 'f', '-not', '-path', '*/.git/*']).output.split('\n').filter(Boolean).map(p => relative(root, p)),
    read: async p => {
      try {
        return readFileSync(p, 'utf8');
      } catch {
        return null;
      }
    },
    readBytes: async p => {
      try {
        return readFileSync(p);
      } catch {
        return null;
      }
    },
    write: async (p, c) => {
      mkdirSync(dirname(p), {recursive: true});
      writeFileSync(p, c);
    },
    search: async (q, d) => sh('grep', ['-rnI', '--exclude-dir=.git', '-e', q, d]).output.replaceAll(`${root}/`, ''),
    run: async (cmd, args) => (cmd === 'git' ? sh(cmd, args) : (scripted(cmd, args) ?? {exitCode: 0, output: ''})),
  };
  return {project, root, file: (p: string) => readFileSync(join(root, p), 'utf8'), cleanup: () => rmSync(root, {recursive: true, force: true})};
}

const usage = {
  inputTokens: {total: 1, noCache: 1, cacheRead: undefined, cacheWrite: undefined},
  outputTokens: {total: 1, text: 1, reasoning: undefined},
};

export const toolStep = (calls: [string, string, object][]) => ({
  stream: simulateReadableStream({
    chunks: [
      ...calls.map(([toolCallId, toolName, input]) => ({type: 'tool-call' as const, toolCallId, toolName, input: JSON.stringify(input)})),
      {type: 'finish' as const, finishReason: {unified: 'tool-calls' as const, raw: undefined}, logprobs: undefined, usage},
    ],
  }),
});

export const textStep = (text: string) => ({
  stream: simulateReadableStream({
    chunks: [
      {type: 'text-start' as const, id: 't'},
      {type: 'text-delta' as const, id: 't', delta: text},
      {type: 'text-end' as const, id: 't'},
      {type: 'finish' as const, finishReason: {unified: 'stop' as const, raw: undefined}, logprobs: undefined, usage},
    ],
  }),
});

export async function runTurn(options: {model: Exclude<LanguageModel, string>; messages: ModelMessage[]; project?: Project; abortSignal?: AbortSignal; keepSandbox?: boolean}) {
  const {stream, turn} = runAgent(options);
  const chunks: AgentChunk[] = [];
  for await (const chunk of stream) chunks.push(chunk);
  let message: AgentMessage | undefined;
  for await (const m of readUIMessageStream<AgentMessage>({stream: convertArrayToReadableStream(chunks)})) message = m;
  return {chunks, message: message!, record: await turn};
}
